-- =====================================================
-- 5. BỔ SUNG: bảng Dân Tộc và bảng Câu Hỏi huấn luyện AI
-- =====================================================

-- Bảng Dân Tộc (nguồn: danh_sach_dan_toc_viet_nam.csv, số liệu 2019)
CREATE TABLE DanToc (
    STT INT PRIMARY KEY,
    TenDanToc NVARCHAR(100) NOT NULL,
    DanSo2019 INT,
    TyLe FLOAT
);

-- Bảng Câu Hỏi - SQL mẫu (nguồn: CauHoi_100_QuanLyVatLieu_NhanVien.csv)
CREATE TABLE CauHoiSQL (
    ID INT PRIMARY KEY,
    NhomCauHoi NVARCHAR(100),
    CauHoiTiengViet NVARCHAR(500),
    SQLQuery NVARCHAR(MAX)
);
GO

