INSERT INTO CauHoiSQL (ID, NhomCauHoi, CauHoiTiengViet, SQLQuery) VALUES
(1, N'Quan ly Nhan vien', N'Hiển thị danh sách toàn bộ nhân viên trong công ty.', N'SELECT * FROM NhanVien;'),
(2, N'Quan ly Nhan vien', N'Cho biết mã nhân viên và họ tên của tất cả nhân viên.', N'SELECT MaNV, HoTen FROM NhanVien;'),
(3, N'Quan ly Nhan vien', N'Thống kê danh sách các chức vụ hiện có và số lượng nhân viên ở mỗi chức vụ.', N'SELECT ChucVu, COUNT(*) AS SoLuong FROM NhanVien GROUP BY ChucVu;'),
(4, N'Quan ly Nhan vien', N'Danh sách các nhân viên giữ chức vụ ''Thu kho''.', N'SELECT MaNV, HoTen FROM NhanVien WHERE ChucVu = ''Thu kho'';'),
(5, N'Quan ly Nhan vien', N'Danh sách các nhân viên giữ chức vụ ''Quan ly kho''.', N'SELECT MaNV, HoTen FROM NhanVien WHERE ChucVu = ''Quan ly kho'';'),
(6, N'Quan ly Nhan vien', N'Những nhân viên nào làm công việc ''Kiem ke''?', N'SELECT MaNV, HoTen FROM NhanVien WHERE ChucVu = ''Kiem ke'';'),
(7, N'Quan ly Nhan vien', N'Liệt kê nhân viên thuộc bộ phận ''Nhan vien ban hang''.', N'SELECT MaNV, HoTen FROM NhanVien WHERE ChucVu = ''Nhan vien ban hang'';'),
(8, N'Quan ly Nhan vien', N'Tìm danh sách nhân viên có họ là ''Nguyen''.', N'SELECT * FROM NhanVien WHERE HoTen LIKE ''Nguyen%'';'),
(9, N'Quan ly Nhan vien', N'Tìm danh sách nhân viên có họ là ''Tran''.', N'SELECT * FROM NhanVien WHERE HoTen LIKE ''Tran%'';'),
(10, N'Quan ly Nhan vien', N'Tìm nhân viên có tên là ''Vinh''.', N'SELECT * FROM NhanVien WHERE HoTen LIKE ''%Vinh'';'),
(11, N'Quan ly Nhan vien', N'Tìm nhân viên có tên chứa chữ ''Tung''.', N'SELECT * FROM NhanVien WHERE HoTen LIKE ''%Tung%'';'),
(12, N'Quan ly Nhan vien', N'Đếm tổng số nhân viên làm việc tại công ty.', N'SELECT COUNT(*) AS TongSoNhanVien FROM NhanVien;'),
(13, N'Quan ly Nhan vien', N'Những nhân viên nào đã từng thực hiện lập phiếu nhập kho?', N'SELECT DISTINCT nv.MaNV, nv.HoTen FROM NhanVien nv JOIN PhieuNhap pn ON nv.MaNV = pn.MaNV;'),
(14, N'Quan ly Nhan vien', N'Những nhân viên nào đã từng thực hiện lập phiếu xuất kho?', N'SELECT DISTINCT nv.MaNV, nv.HoTen FROM NhanVien nv JOIN PhieuXuat px ON nv.MaNV = px.MaNV;'),
(15, N'Quan ly Nhan vien', N'Những nhân viên nào vừa lập phiếu nhập vừa lập phiếu xuất?', N'SELECT DISTINCT MaNV FROM PhieuNhap INTERSECT SELECT DISTINCT MaNV FROM PhieuXuat;'),
(16, N'Quan ly Nhan vien', N'Những nhân viên nào chưa từng lập phiếu nhập hay phiếu xuất nào?', N'SELECT MaNV, HoTen FROM NhanVien WHERE MaNV NOT IN (SELECT MaNV FROM PhieuNhap UNION SELECT MaNV FROM PhieuXuat);'),
(17, N'Quan ly Nhan vien', N'Thống kê số lượng phiếu nhập mà mỗi nhân viên đã lập.', N'SELECT nv.MaNV, nv.HoTen, COUNT(pn.MaPN) AS SoPhieuNhap FROM NhanVien nv LEFT JOIN PhieuNhap pn ON nv.MaNV = pn.MaNV GROUP BY nv.MaNV, nv.HoTen;'),
(18, N'Quan ly Nhan vien', N'Thống kê số lượng phiếu xuất mà mỗi nhân viên đã lập.', N'SELECT nv.MaNV, nv.HoTen, COUNT(px.MaPX) AS SoPhieuXuat FROM NhanVien nv LEFT JOIN PhieuXuat px ON nv.MaNV = px.MaNV GROUP BY nv.MaNV, nv.HoTen;'),
(19, N'Quan ly Nhan vien', N'Top 5 nhân viên lập nhiều phiếu xuất nhất.', N'SELECT nv.MaNV, nv.HoTen, COUNT(px.MaPX) AS SoPhieu FROM NhanVien nv JOIN PhieuXuat px ON nv.MaNV = px.MaNV GROUP BY nv.MaNV, nv.HoTen ORDER BY SoPhieu DESC LIMIT 5;'),
(20, N'Quan ly Nhan vien', N'Top 5 nhân viên lập nhiều phiếu nhập nhất.', N'SELECT nv.MaNV, nv.HoTen, COUNT(pn.MaPN) AS SoPhieu FROM NhanVien nv JOIN PhieuNhap pn ON nv.MaNV = pn.MaNV GROUP BY nv.MaNV, nv.HoTen ORDER BY SoPhieu DESC LIMIT 5;'),
(21, N'Quan ly Nhan vien', N'Cho biết nhân viên nào xử lý tổng giá trị xuất hàng lớn nhất.', N'SELECT nv.MaNV, nv.HoTen, SUM(ct.SoLuong * ct.DonGia) AS TongGiaTriXuat FROM NhanVien nv JOIN PhieuXuat px ON nv.MaNV = px.MaNV JOIN ChiTietPhieuXuat ct ON px.MaPX = ct.MaPX GROUP BY nv.MaNV, nv.HoTen ORDER BY TongGiaTriXuat DESC LIMIT 1;'),
(22, N'Quan ly Nhan vien', N'Hiển thị danh sách nhân viên được sắp xếp theo tên từ A đến Z.', N'SELECT * FROM NhanVien ORDER BY HoTen ASC;'),
(23, N'Quan ly Nhan vien', N'Cho biết các nhân viên có mã nhân viên bắt đầu bằng ''NV0''.', N'SELECT * FROM NhanVien WHERE MaNV LIKE ''NV0%'';'),
(24, N'Quan ly Nhan vien', N'Chức vụ nào có số lượng nhân viên đông nhất?', N'SELECT ChucVu, COUNT(*) AS SoLuong FROM NhanVien GROUP BY ChucVu ORDER BY SoLuong DESC LIMIT 1;'),
(25, N'Quan ly Nhan vien', N'Có bao nhiêu nhân viên là ''Ke toan''?', N'SELECT COUNT(*) AS SoKeToan FROM NhanVien WHERE ChucVu = ''Ke toan'';'),
(26, N'Quan ly Kho & Nha Cung Cap', N'Hiển thị toàn bộ thông tin các kho hàng.', N'SELECT * FROM Kho;'),
(27, N'Quan ly Kho & Nha Cung Cap', N'Cho biết tên kho và địa chỉ của từng kho.', N'SELECT TenKho, DiaChi FROM Kho;'),
(28, N'Quan ly Kho & Nha Cung Cap', N'Đếm tổng số kho hàng hiện có.', N'SELECT COUNT(*) AS TongSoKho FROM Kho;'),
(29, N'Quan ly Kho & Nha Cung Cap', N'Hiển thị danh sách tất cả các nhà cung cấp.', N'SELECT * FROM NhaCungCap;'),
(30, N'Quan ly Kho & Nha Cung Cap', N'Cho biết tên nhà cung cấp và số điện thoại liên hệ.', N'SELECT TenNCC, DienThoai FROM NhaCungCap;'),
(31, N'Quan ly Kho & Nha Cung Cap', N'Danh sách các nhà cung cấp ở địa bàn ''Quy Nhon''.', N'SELECT * FROM NhaCungCap WHERE DiaChi LIKE ''%Quy Nhon%'';'),
(32, N'Quan ly Kho & Nha Cung Cap', N'Danh sách các nhà cung cấp ở ''Da Nang''.', N'SELECT * FROM NhaCungCap WHERE DiaChi LIKE ''%Da Nang%'';'),
(33, N'Quan ly Kho & Nha Cung Cap', N'Thống kê tổng số lượng phiếu nhập đến từ mỗi nhà cung cấp.', N'SELECT ncc.MaNCC, ncc.TenNCC, COUNT(pn.MaPN) AS SoPhieuNhap FROM NhaCungCap ncc LEFT JOIN PhieuNhap pn ON ncc.MaNCC = pn.MaNCC GROUP BY ncc.MaNCC, ncc.TenNCC;'),
(34, N'Quan ly Kho & Nha Cung Cap', N'Thống kê tổng tiền hàng đã nhập từ mỗi nhà cung cấp.', N'SELECT ncc.MaNCC, ncc.TenNCC, SUM(ct.SoLuong * ct.DonGia) AS TongGiaTriNhap FROM NhaCungCap ncc JOIN PhieuNhap pn ON ncc.MaNCC = pn.MaNCC JOIN ChiTietPhieuNhap ct ON pn.MaPN = ct.MaPN GROUP BY ncc.MaNCC, ncc.TenNCC;'),
(35, N'Quan ly Kho & Nha Cung Cap', N'Nhà cung cấp nào có tổng giá trị giao dịch nhập hàng lớn nhất?', N'SELECT ncc.MaNCC, ncc.TenNCC, SUM(ct.SoLuong * ct.DonGia) AS TongGiaTri FROM NhaCungCap ncc JOIN PhieuNhap pn ON ncc.MaNCC = pn.MaNCC JOIN ChiTietPhieuNhap ct ON pn.MaPN = ct.MaPN GROUP BY ncc.MaNCC, ncc.TenNCC ORDER BY TongGiaTri DESC LIMIT 1;'),
(36, N'Quan ly Kho & Nha Cung Cap', N'Nhà cung cấp nào chưa có giao dịch nhập hàng nào?', N'SELECT * FROM NhaCungCap WHERE MaNCC NOT IN (SELECT DISTINCT MaNCC FROM PhieuNhap);'),
(37, N'Quan ly Kho & Nha Cung Cap', N'Những vật liệu nào đã được nhập từ nhà cung cấp có mã ''NCC01''?', N'SELECT DISTINCT ct.MaVT FROM PhieuNhap pn JOIN ChiTietPhieuNhap ct ON pn.MaPN = ct.MaPN WHERE pn.MaNCC = ''NCC01'';'),
(38, N'Quan ly Kho & Nha Cung Cap', N'Hiển thị nhà cung cấp kèm theo lần nhập hàng gần đây nhất.', N'SELECT ncc.MaNCC, ncc.TenNCC, MAX(pn.NgayNhap) AS NgayNhapMoiNhat FROM NhaCungCap ncc LEFT JOIN PhieuNhap pn ON ncc.MaNCC = pn.MaNCC GROUP BY ncc.MaNCC, ncc.TenNCC;'),
(39, N'Quan ly Kho & Nha Cung Cap', N'Tìm nhà cung cấp có tên chứa chữ ''Nam A''.', N'SELECT * FROM NhaCungCap WHERE TenNCC LIKE ''%Nam A%'';'),
(40, N'Quan ly Kho & Nha Cung Cap', N'Cho biết tổng số nhà cung cấp đã từng hợp tác nhập hàng.', N'SELECT COUNT(DISTINCT MaNCC) AS SoNCCCoGiaoDich FROM PhieuNhap;'),
(41, N'Quan ly Kho & Nha Cung Cap', N'Liệt kê kho có tên chứa từ ''Tong''.', N'SELECT * FROM Kho WHERE TenKho LIKE ''%Tong%'';'),
(42, N'Quan ly Kho & Nha Cung Cap', N'Kho nào nằm ở địa chỉ ''150 An Duong Vuong''?', N'SELECT * FROM Kho WHERE DiaChi LIKE ''%150 An Duong Vuong%'';'),
(43, N'Quan ly Kho & Nha Cung Cap', N'Liệt kê mã phiếu nhập và tên nhà cung cấp tương ứng.', N'SELECT pn.MaPN, ncc.TenNCC FROM PhieuNhap pn JOIN NhaCungCap ncc ON pn.MaNCC = ncc.MaNCC;'),
(44, N'Quan ly Kho & Nha Cung Cap', N'Đếm số lượt nhập hàng theo từng tháng trong năm.', N'SELECT strftime(''%Y-%m'', NgayNhap) AS Thang, COUNT(*) AS SoLuotNhap FROM PhieuNhap GROUP BY Thang;'),
(45, N'Quan ly Kho & Nha Cung Cap', N'Cho biết ngày nhập hàng đầu tiên lưu trong hệ thống.', N'SELECT MIN(NgayNhap) AS NgayNhapDauTien FROM PhieuNhap;'),
(46, N'Quan ly Nhap kho & Vat lieu', N'Hiển thị toàn bộ danh sách phiếu nhập.', N'SELECT * FROM PhieuNhap;'),
(47, N'Quan ly Kho & Vat lieu', N'Hiển thị toàn bộ chi tiết của tất cả các phiếu nhập.', N'SELECT * FROM ChiTietPhieuNhap;'),
(48, N'Quan ly Nhap kho & Vat lieu', N'Danh sách chi tiết phiếu nhập gồm: Mã phiếu, Mã vật liệu, Số lượng, Đơn giá và Thành tiền.', N'SELECT MaPN, MaVT, SoLuong, DonGia, (SoLuong * DonGia) AS ThanhTien FROM ChiTietPhieuNhap;'),
(49, N'Quan ly Nhap kho & Vat lieu', N'Tính tổng thành tiền của từng phiếu nhập.', N'SELECT MaPN, SUM(SoLuong * DonGia) AS TongTienPhieuNhap FROM ChiTietPhieuNhap GROUP BY MaPN;'),
(50, N'Quan ly Nhap kho & Vat lieu', N'Phiếu nhập nào có tổng giá trị lớn nhất?', N'SELECT MaPN, SUM(SoLuong * DonGia) AS TongGiaTri FROM ChiTietPhieuNhap GROUP BY MaPN ORDER BY TongGiaTri DESC LIMIT 1;'),
(51, N'Quan ly Nhap kho & Vat lieu', N'Tính tổng số lượng nhập của từng mã vật liệu.', N'SELECT MaVT, SUM(SoLuong) AS TongSoLuongNhap FROM ChiTietPhieuNhap GROUP BY MaVT;'),
(52, N'Quan ly Nhap kho & Vat lieu', N'Tính tổng giá trị nhập kho của từng vật liệu.', N'SELECT MaVT, SUM(SoLuong * DonGia) AS TongGiaTriNhap FROM ChiTietPhieuNhap GROUP BY MaVT;'),
(53, N'Quan ly Nhap kho & Vat lieu', N'Cho biết đơn giá nhập trung bình của từng mã vật liệu.', N'SELECT MaVT, AVG(DonGia) AS DonGiaTrungBinh FROM ChiTietPhieuNhap GROUP BY MaVT;'),
(54, N'Quan ly Nhap kho & Vat lieu', N'Liệt kê các phiếu nhập được thực hiện trong tháng 6/2026.', N'SELECT * FROM PhieuNhap WHERE NgayNhap BETWEEN ''2026-06-01'' AND ''2026-06-30'';'),
(55, N'Quan ly Nhap kho & Vat lieu', N'Tìm chi tiết phiếu nhập có số lượng lớn hơn 300.', N'SELECT * FROM ChiTietPhieuNhap WHERE SoLuong > 300;'),
(56, N'Quan ly Nhap kho & Vat lieu', N'Tìm chi tiết phiếu nhập có đơn giá từ 50,000 đến 100,000 VNĐ.', N'SELECT * FROM ChiTietPhieuNhap WHERE DonGia BETWEEN 50000 AND 100000;'),
(57, N'Quan ly Nhap kho & Vat lieu', N'Vật liệu nào có đơn giá nhập cao nhất?', N'SELECT MaVT, DonGia FROM ChiTietPhieuNhap ORDER BY DonGia DESC LIMIT 1;'),
(58, N'Quan ly Nhap kho & Vat lieu', N'Vật liệu nào có đơn giá nhập thấp nhất?', N'SELECT MaVT, DonGia FROM ChiTietPhieuNhap ORDER BY DonGia ASC LIMIT 1;'),
(59, N'Quan ly Nhap kho & Vat lieu', N'Cho biết thông tin các phiếu nhập do nhân viên có mã ''NV01'' lập.', N'SELECT * FROM PhieuNhap WHERE MaNV = ''NV01'';'),
(60, N'Quan ly Nhap kho & Vat lieu', N'Hiển thị thông tin phiếu nhập kèm tên nhân viên và tên nhà cung cấp.', N'SELECT pn.MaPN, pn.NgayNhap, nv.HoTen AS TenNhanVien, ncc.TenNCC FROM PhieuNhap pn JOIN NhanVien nv ON pn.MaNV = nv.MaNV JOIN NhaCungCap ncc ON pn.MaNCC = ncc.MaNCC;'),
(61, N'Quan ly Nhap kho & Vat lieu', N'Mã vật liệu ''VT01'' đã được nhập tổng cộng bao nhiêu?', N'SELECT SUM(SoLuong) AS TongNhapVT01 FROM ChiTietPhieuNhap WHERE MaVT = ''VT01'';'),
(62, N'Quan ly Nhap kho & Vat lieu', N'Những phiếu nhập nào nhập vật liệu ''VT02''?', N'SELECT DISTINCT MaPN FROM ChiTietPhieuNhap WHERE MaVT = ''VT02'';'),
(63, N'Quan ly Nhap kho & Vat lieu', N'Tổng toàn bộ chi phí nhập hàng trong kho là bao nhiêu?', N'SELECT SUM(SoLuong * DonGia) AS TongChiPhiNhap FROM ChiTietPhieuNhap;'),
(64, N'Quan ly Nhap kho & Vat lieu', N'Có bao nhiêu lượt nhập mã vật liệu riêng biệt?', N'SELECT COUNT(DISTINCT MaVT) AS SoVatLieuDaNhap FROM ChiTietPhieuNhap;'),
(65, N'Quan ly Nhap kho & Vat lieu', N'Liệt kê phiếu nhập được thực hiện vào ngày ''2026-06-01''.', N'SELECT * FROM PhieuNhap WHERE NgayNhap = ''2026-06-01'';'),
(66, N'Quan ly Nhap kho & Vat lieu', N'Đếm số lượng vật liệu được nhập trong mỗi phiếu nhập.', N'SELECT MaPN, COUNT(MaVT) AS SoLoaiVatLieu FROM ChiTietPhieuNhap GROUP BY MaPN;'),
(67, N'Quan ly Nhap kho & Vat lieu', N'Danh sách phiếu nhập sắp xếp theo ngày nhập mới nhất.', N'SELECT * FROM PhieuNhap ORDER BY NgayNhap DESC;'),
(68, N'Quan ly Nhap kho & Vat lieu', N'Các mặt hàng vật liệu nào có tổng số lượng nhập lớn hơn 200?', N'SELECT MaVT, SUM(SoLuong) AS TongSL FROM ChiTietPhieuNhap GROUP BY MaVT HAVING SUM(SoLuong) > 200;'),
(69, N'Quan ly Nhap kho & Vat lieu', N'Các mặt hàng vật liệu nào có đơn giá nhập trung bình trên 80,000?', N'SELECT MaVT, AVG(DonGia) AS DGTB FROM ChiTietPhieuNhap GROUP BY MaVT HAVING AVG(DonGia) > 80000;'),
(70, N'Quan ly Nhap kho & Vat lieu', N'Hiển thị danh sách phiếu nhập cùng tổng tiền của từng phiếu.', N'SELECT pn.MaPN, pn.NgayNhap, SUM(ct.SoLuong * ct.DonGia) AS TongTien FROM PhieuNhap pn JOIN ChiTietPhieuNhap ct ON pn.MaPN = ct.MaPN GROUP BY pn.MaPN, pn.NgayNhap;'),
(71, N'Quan ly Xuat kho & Ban hang', N'Hiển thị toàn bộ danh sách các phiếu xuất.', N'SELECT * FROM PhieuXuat;'),
(72, N'Quan ly Xuat kho & Ban hang', N'Hiển thị toàn bộ chi tiết các phiếu xuất.', N'SELECT * FROM ChiTietPhieuXuat;'),
(73, N'Quan ly Xuat kho & Ban hang', N'Liệt kê thông tin phiếu xuất gồm: Mã phiếu xuất, Ngày xuất, Người nhận và Tên nhân viên lập.', N'SELECT px.MaPX, px.NgayXuat, px.NguoiNhan, nv.HoTen AS TenNhanVien FROM PhieuXuat px JOIN NhanVien nv ON px.MaNV = nv.MaNV;'),
(74, N'Quan ly Xuat kho & Ban hang', N'Tính thành tiền cho từng dòng chi tiết xuất kho.', N'SELECT MaPX, MaVT, SoLuong, DonGia, (SoLuong * DonGia) AS ThanhTien FROM ChiTietPhieuXuat;'),
(75, N'Quan ly Xuat kho & Ban hang', N'Tính tổng giá trị của mỗi phiếu xuất.', N'SELECT MaPX, SUM(SoLuong * DonGia) AS TongTienPhieuXuat FROM ChiTietPhieuXuat GROUP BY MaPX;'),
(76, N'Quan ly Xuat kho & Ban hang', N'Phiếu xuất nào có giá trị lớn nhất?', N'SELECT MaPX, SUM(SoLuong * DonGia) AS TongGiaTri FROM ChiTietPhieuXuat GROUP BY MaPX ORDER BY TongGiaTri DESC LIMIT 1;'),
(77, N'Quan ly Xuat kho & Ban hang', N'Tính tổng số lượng xuất theo từng mã vật liệu.', N'SELECT MaVT, SUM(SoLuong) AS TongSoLuongXuat FROM ChiTietPhieuXuat GROUP BY MaVT;'),
(78, N'Quan ly Xuat kho & Ban hang', N'Tính tổng doanh thu xuất hàng theo từng vật liệu.', N'SELECT MaVT, SUM(SoLuong * DonGia) AS TongDoanhThu FROM ChiTietPhieuXuat GROUP BY MaVT;'),
(79, N'Quan ly Xuat kho & Ban hang', N'Thống kê danh sách khách hàng / người nhận và tổng tiền đã xuất cho họ.', N'SELECT px.NguoiNhan, SUM(ct.SoLuong * ct.DonGia) AS TongTienXuat FROM PhieuXuat px JOIN ChiTietPhieuXuat ct ON px.MaPX = ct.MaPX GROUP BY px.NguoiNhan;'),
(80, N'Quan ly Xuat kho & Ban hang', N'Người nhận / Khách hàng nào mua hàng với tổng giá trị lớn nhất?', N'SELECT px.NguoiNhan, SUM(ct.SoLuong * ct.DonGia) AS TongTien FROM PhieuXuat px JOIN ChiTietPhieuXuat ct ON px.MaPX = ct.MaPX GROUP BY px.NguoiNhan ORDER BY TongTien DESC LIMIT 1;'),
(81, N'Quan ly Xuat kho & Ban hang', N'Các phiếu xuất được thực hiện trong tháng 6/2026.', N'SELECT * FROM PhieuXuat WHERE NgayXuat BETWEEN ''2026-06-01'' AND ''2026-06-30'';'),
(82, N'Quan ly Xuat kho & Ban hang', N'Cho biết ngày xuất hàng mới nhất.', N'SELECT MAX(NgayXuat) AS NgayXuatMoiNhat FROM PhieuXuat;'),
(83, N'Quan ly Xuat kho & Ban hang', N'Cho biết ngày xuất hàng đầu tiên.', N'SELECT MIN(NgayXuat) AS NgayXuatDauTien FROM PhieuXuat;'),
(84, N'Quan ly Xuat kho & Ban hang', N'Tìm các phiếu xuất xuất cho công ty có tên chứa ''ABC''.', N'SELECT * FROM PhieuXuat WHERE NguoiNhan LIKE ''%ABC%'';'),
(85, N'Quan ly Xuat kho & Ban hang', N'Tổng số lượng vật liệu ''VT01'' đã xuất ra khỏi kho là bao nhiêu?', N'SELECT SUM(SoLuong) AS TongXuatVT01 FROM ChiTietPhieuXuat WHERE MaVT = ''VT01'';'),
(86, N'Quan ly Xuat kho & Ban hang', N'Tổng doanh thu thu được từ tất cả các phiếu xuất.', N'SELECT SUM(SoLuong * DonGia) AS TongDoanhThuXuat FROM ChiTietPhieuXuat;'),
(87, N'Quan ly Xuat kho & Ban hang', N'Đếm số lượng phiếu xuất được lập bởi nhân viên ''NV02''.', N'SELECT COUNT(*) AS SoPhieuNV02 FROM PhieuXuat WHERE MaNV = ''NV02'';'),
(88, N'Quan ly Xuat kho & Ban hang', N'Mặt hàng nào có số lượng xuất cao nhất trong một lần xuất?', N'SELECT MaVT, SoLuong FROM ChiTietPhieuXuat ORDER BY SoLuong DESC LIMIT 1;'),
(89, N'Quan ly Xuat kho & Ban hang', N'Hiển thị danh sách phiếu xuất cùng tổng số loại vật liệu có trong phiếu.', N'SELECT MaPX, COUNT(DISTINCT MaVT) AS SoLoaiVatLieu FROM ChiTietPhieuXuat GROUP BY MaPX;'),
(90, N'Quan ly Xuat kho & Ban hang', N'Sắp xếp danh sách phiếu xuất theo thứ tự ngày xuất tăng dần.', N'SELECT * FROM PhieuXuat ORDER BY NgayXuat ASC;'),
(91, N'Bao cao Tong hop & Ton kho', N'Báo cáo tổng hợp số lượng nhập và số lượng xuất của tất cả các mã vật liệu.', N'SELECT COALESCE(n.MaVT, x.MaVT) AS MaVT, COALESCE(n.TongNhap, 0) AS TongNhap, COALESCE(x.TongXuat, 0) AS TongXuat FROM (SELECT MaVT, SUM(SoLuong) AS TongNhap FROM ChiTietPhieuNhap GROUP BY MaVT) n FULL OUTER JOIN (SELECT MaVT, SUM(SoLuong) AS TongXuat FROM ChiTietPhieuXuat GROUP BY MaVT) x ON n.MaVT = x.MaVT;'),
(92, N'Bao cao Tong hop & Ton kho', N'Tính lượng tồn kho lý thuyết (Tổng nhập - Tổng xuất) của từng vật liệu.', N'SELECT COALESCE(n.MaVT, x.MaVT) AS MaVT, (COALESCE(n.TongNhap, 0) - COALESCE(x.TongXuat, 0)) AS TonKho FROM (SELECT MaVT, SUM(SoLuong) AS TongNhap FROM ChiTietPhieuNhap GROUP BY MaVT) n FULL OUTER JOIN (SELECT MaVT, SUM(SoLuong) AS TongXuat FROM ChiTietPhieuXuat GROUP BY MaVT) x ON n.MaVT = x.MaVT;'),
(93, N'Bao cao Tong hop & Ton kho', N'Tính tổng chênh lệch giữa giá trị nhập và giá trị xuất của kho.', N'SELECT (SELECT SUM(SoLuong * DonGia) FROM ChiTietPhieuNhap) - (SELECT SUM(SoLuong * DonGia) FROM ChiTietPhieuXuat) AS ChenhLechGiaTri;'),
(94, N'Bao cao Tong hop & Ton kho', N'Thống kê tổng số phiếu nhập và tổng số phiếu xuất hiện có.', N'SELECT (SELECT COUNT(*) FROM PhieuNhap) AS TongPhieuNhap, (SELECT COUNT(*) FROM PhieuXuat) AS TongPhieuXuat;'),
(95, N'Bao cao Tong hop & Ton kho', N'Liệt kê mã các vật liệu vừa có lịch sử nhập vừa có lịch sử xuất.', N'SELECT DISTINCT MaVT FROM ChiTietPhieuNhap INTERSECT SELECT DISTINCT MaVT FROM ChiTietPhieuXuat;'),
(96, N'Bao cao Tong hop & Ton kho', N'Liệt kê mã các vật liệu đã từng nhập nhưng chưa từng xuất.', N'SELECT DISTINCT MaVT FROM ChiTietPhieuNhap EXCEPT SELECT DISTINCT MaVT FROM ChiTietPhieuXuat;'),
(97, N'Bao cao Tong hop & Ton kho', N'Tính đơn giá trung bình chung của vật liệu trên cả phiếu nhập và phiếu xuất.', N'SELECT MaVT, AVG(DonGia) AS DonGiaTrungBinh FROM (SELECT MaVT, DonGia FROM ChiTietPhieuNhap UNION ALL SELECT MaVT, DonGia FROM ChiTietPhieuXuat) Combined GROUP BY MaVT;'),
(98, N'Bao cao Tong hop & Ton kho', N'Tổng giá trị vật liệu tồn kho tính theo giá nhập gần nhất.', N'SELECT SUM((COALESCE(n.TongNhap, 0) - COALESCE(x.TongXuat, 0)) * n.DonGiaGannhat) AS TongGiaTriTon FROM (SELECT MaVT, SUM(SoLuong) AS TongNhap, AVG(DonGia) AS DonGiaGannhat FROM ChiTietPhieuNhap GROUP BY MaVT) n LEFT JOIN (SELECT MaVT, SUM(SoLuong) AS TongXuat FROM ChiTietPhieuXuat GROUP BY MaVT) x ON n.MaVT = x.MaVT;'),
(99, N'Bao cao Tong hop & Ton kho', N'Thống kê tổng số giao dịch (cả nhập lẫn xuất) theo từng tháng.', N'SELECT strftime(''%Y-%m'', NgayGiaoDich) AS Thang, COUNT(*) AS TongGiaoDich FROM (SELECT NgayNhap AS NgayGiaoDich FROM PhieuNhap UNION ALL SELECT NgayXuat AS NgayGiaoDich FROM PhieuXuat) GROUP BY Thang;'),
(100, N'Bao cao Tong hop & Ton kho', N'Cho biết tổng số nhân viên đã từng tham gia vào quy trình nhập hoặc xuất kho.', N'SELECT COUNT(DISTINCT MaNV) AS SoNhanVienHoatDong FROM (SELECT MaNV FROM PhieuNhap UNION SELECT MaNV FROM PhieuXuat);');
